import{_ as e,c as p,o as r,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"巽","description":"高岛易断 - 巽","frontmatter":{"title":"巽","description":"高岛易断 - 巽"},"headers":[],"relativePath":"zh/classics/takashima/057.md","filePath":"zh/classics/takashima/057.md"}'),i={name:"zh/classics/takashima/057.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="巽" tabindex="-1">巽 <a class="header-anchor" href="#巽" aria-label="Permalink to “巽”">​</a></h1><h2 id="巽-1" tabindex="-1">巽 <a class="header-anchor" href="#巽-1" aria-label="Permalink to “巽”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>巽：小亨，利有攸往，利见大人。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《巽》本《乾》体，《乾》德元亨，亦称大亨，初动成《巽》，纯刚化柔，故为“小亨”。卦《彖》言“利有攸往”者，《大过》、《恒》、《益》，皆取《巽》也，过刚之人，所往必穷，《巽》以《坤》初一阴入《乾》，以柔济刚，黾勉前往，《巽》为利，故“利有攸往”。“大人”，指二五，《巽》二五皆《乾》体，《乾》二五皆“利见大人”，《巽》之《彖》辞，从《乾》来，《乾》为利，上互《离》，《离》为见，故《巽》《彖》亦曰“利见大人”。</p><h2 id="象辞" tabindex="-1">象辞 <a class="header-anchor" href="#象辞" aria-label="Permalink to “象辞”">​</a></h2><p>随风，巽。君子以申命行事。</p><h2 id="象辞注" tabindex="-1">象辞注 <a class="header-anchor" href="#象辞注" aria-label="Permalink to “象辞注”">​</a></h2><p>“随”者，相继之义，“申命行事”者，申告君命而奉行之也。《巽》为从，从者，随也；又《巽》为风，以风随风，无乎不入，故曰“随风”。“随风”者，犹言从风，即“重巽”之谓也。风行相随，所向皆靡，号令所施，顺合民心，民无不从，所谓“君子之德风”也。又上卦之《巽》，为大君施命之象。下卦之《巽》，为臣民奉命之象，夫君命臣行，君臣之大义也，故曰“君子以申命行事”。</p><h2 id="占断" tabindex="-1">占断 <a class="header-anchor" href="#占断" aria-label="Permalink to “占断”">​</a></h2><p>○　问时运：运途顺遂，百事盛宜。</p><p>○　问营商：商业最宜随机应变，听命而行，斯可获利。</p><p>○　问功名：“风从虎”，有虎变之象焉。</p><p>○　问战征：军令之行，捷如风火，令出惟行，无可迟疑。</p><p>○　问婚姻：凭父母之命，媒妁之言，礼之正也。夫唱妇随，百年偕老，吉。</p><p>○　问疾病：是风痹之症，须人扶持而行。</p><p>○　问讼事：须重申禀诉。</p><p>○　问失物：为风飘失，须重番寻觅，或可复得。</p><p>○　问六甲：生女。</p><h2 id="初六解" tabindex="-1">初六解 <a class="header-anchor" href="#初六解" aria-label="Permalink to “初六解”">​</a></h2><p>初爻阴柔居下，为《巽》之主，巽，顺也，柔顺少断，故象为进退。狐疑不决，每见于发念之初，蓄疑败谋，此志之所以不治也。《巽》反成《兑》，《兑》为武人，武人果决，足以断疑，故曰“利武人之贞”。“贞”者，正也，斯刚强奋发之气，可以矫逡巡畏缩之偏。《象传》释以“志治”，是以武治疑，即以《兑》制《巽》也。</p><h2 id="初六占" tabindex="-1">初六占 <a class="header-anchor" href="#初六占" aria-label="Permalink to “初六占”">​</a></h2><p>○　问时运：运途不正，心神犹豫，是以谋事皆颠倒无成。</p><p>○　问营商：《巽》本为利，因疑而败，以断而成，知犹豫者必难获利也。</p><p>○　问功名：就武可成。</p><p>○　问婚姻：不在彬彬文士，而宜桓桓虎臣。</p><p>○　问家宅：此宅朝东南，地位不当，进退不便，宜改朝西为利。</p><p>○　问六甲：生女。</p><h2 id="初六案例" tabindex="-1">初六案例 <a class="header-anchor" href="#初六案例" aria-label="Permalink to “初六案例”">​</a></h2><p>友人某来，请占气运，筮得《巽》之《小畜》。</p><p>断曰：巽者，风也，风之为物，或东或西，来去无常，犹多疑之人，进退无定也。“武人”者，取其刚果能断也。今足下占气运，得此初爻，《巽》为七八月之卦，《巽》又为木，知足下现交木运，时值初秋，木因风吹，摇动不定，喻言人心疑虑，以致进退不决。“武人”者肃杀之象也，天以肃杀而成秋，犹人以刚决而成事，足下一味巽柔，临事不断，浑如随风飘荡，毫无定见，本为畏事，不知反以多事。劝足下当以沉潜刚克处之，为得其正矣。</p><h2 id="九二解" tabindex="-1">九二解 <a class="header-anchor" href="#九二解" aria-label="Permalink to “九二解”">​</a></h2><p>《巽》为床，床下为初，《巽》以一阴在下，故曰“床下”。凡阴气中人，必使其人神魂不定，疑鬼疑神，若有物凭之者焉，非用刚克，不能去其疑妄。“史”者掌卜筮之官，“巫”者掌祓禳之官，皆取诸《兑》象。《兑》又为附决，用史以释疑，用巫以禳灾，斯得感格于上下神祗，而吉祥汇集也，故曰“纷若，吉”。“纷”，众多之称，“若”，语辞。《象传》以“得中”释之，谓能行得其中，以感孚夫神祗，是以有“纷若”之吉也。</p><h2 id="九二占" tabindex="-1">九二占 <a class="header-anchor" href="#九二占" aria-label="Permalink to “九二占”">​</a></h2><p>○　问时运：得神明保佑，运途多吉。</p><p>○　问营商：凡贩运货物，有不决者，宜问诸卜筮，自能迪吉。</p><p>○　问功名：得有神助，吉。</p><p>○　问战征：地位既低，进退两难，当此之时，惟告求神明，自可获吉。无咎。</p><p>○　问婚姻：卜之则吉。</p><p>○　问家宅：宜祷。</p><p>○　问疾病：宜祭祷床公床婆，自得无咎。</p><p>○　问六甲：生女。</p><h2 id="九二案例" tabindex="-1">九二案例 <a class="header-anchor" href="#九二案例" aria-label="Permalink to “九二案例”">​</a></h2><p>某缙绅来，请占方今时势，筮得《巽》之《渐》。</p><p>断曰：巽者，柔顺也，其为人必柔弱无能，亦优柔寡断。九二曰“巽在床下”，有匍匐床下，俯首乞怜之状也。足下占时势，得此爻辞，知方今时势，朝野上下，一以巽谀成风，以忠厚为迂疏，以奸诈为得计，所谓伺候于公卿之门，奔走于形势之途，今之士大夫所恃为进身之要策也。不知愈趋愈下，世道日衰，而祸患之来，皆其自取。爻辞曰“用史巫纷若，吉”，盖明示以卑《巽》之道，用之权贵，则谓谄谀，用之于神明，则谓诚求，诚求于神，神必佑之，是以吉而无咎也。足下有心挽回时势，可知所从事矣。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>三爻以阳居阳，处下《巽》之极。“频”者，数也，下《巽》终而上《巽》接，故曰“频巽”。所谓“刚巽乎中正”，固非徒取夫巽也，九三乃亟亟于巽以继巽，若一巽为不足，而又加一巽焉，是第知巽之为巽，而不知制《巽》之道，偏于巽者也。偏则吝矣，吝则穷矣。《象传》以“志穷”释之，三居《巽》之终，志卑道屈，是终穷也。</p><h2 id="九三占" tabindex="-1">九三占 <a class="header-anchor" href="#九三占" aria-label="Permalink to “九三占”">​</a></h2><p>○　问时运：目下运途卑低，未免为人所贱。</p><p>○　问战征：一味委靡，力弱志衰，难以免辱。</p><p>○　问功名：卑而又卑，所得亦微矣。</p><p>○　问营商：巽顺过甚，未能与人争强，何能获利？</p><p>○　问婚姻：门户低微，成亦可羞。</p><p>○　问家宅：屋宇低小，必是贫穷之户。</p><p>○　问讼事：柔弱被欺，咎亦自取。</p><p>○　问六甲：生女。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>友人某来，请占气运，筮得《巽》之《涣》。</p><p>断曰：九三处内外卦之间，巽而又巽，谓之“重巽”，是一味委靡，不能免祸，反致启羞。足下占气运，得此爻辞，知目下气运柔弱，无力奋兴。当以《彖传》所谓“刚巽乎中正”者处之，斯巽得其济，而足以自强，则其志可行，其道不穷矣。</p><p>明治三十年，占贵族院气运，筮得《巽》之《涣》。</p><p>断曰：爻曰“频巽”，是上下皆《巽》，《正义》以频为频戚忧戚之容，谓志意穷屈，不得申遂，处《巽》之时，只得受其屈辱，故曰“频巽，吝”。今占贵族院，得此爻辞，知方今院中议员，皆以巽顺为怀，行《巽》之道，处《巽》之时，志穷力弱，只得受其屈辱，以致频戚不乐也。本年贵族院，必无功绩可见。</p><h2 id="六四解" tabindex="-1">六四解 <a class="header-anchor" href="#六四解" aria-label="Permalink to “六四解”">​</a></h2><p>四为重《巽》之主，得正而顺乎刚，故“悔亡”。四与初同体，初曰“利武人”，取《离》之为甲胄，为弓矢，四曰“田”，亦取《离》之为网罟也，其象亦相同。《周礼》四时之田，皆前期示戒，及其听命，即《大象》所云“申命行事”之义也。“获”，田所获也”。“三品”者，一为干豆，二为宾客，三为充君之庖。《象传》以“有功”释之，如《诗·豳风》所咏：“献豜私豵，载续武功”，谓致禽兽而有功也。一云，《解》九二曰“田获三狐”，言去小人也；《巽》九四曰“田获三品”，言用君子也。</p><h2 id="六四占" tabindex="-1">六四占 <a class="header-anchor" href="#六四占" aria-label="Permalink to “六四占”">​</a></h2><p>○　问时运：运途得正，灾悔俱亡，出而有功也。</p><p>○　问战征：从东南进兵，自得斩获有功。</p><p>○　问功名：当以献功获赏，出身成名。</p><p>○　问营商：当以采办皮革羽毛等品致富。</p><p>○　问婚姻：婚礼，古时弋凫射雀，亦田象。</p><p>○　问疾病：曰“悔亡”，病必可愈。</p><p>○　问失物：可得。</p><p>○　问六甲：生女。</p><h2 id="六四案例" tabindex="-1">六四案例 <a class="header-anchor" href="#六四案例" aria-label="Permalink to “六四案例”">​</a></h2><p>横滨某商来谓曰：仆今欲谋一事，请占其得失。筮得《巽》之《姤》。</p><p>断曰：《巽》为近市利三倍之卦，六四为重《巽》之主，足以当之。今占得四爻，四“悔亡，田获三品”，是明言无悔而有获也。子之谋事，其有大利可知也。子勿疑，举全力而从事可也。某大喜，乃汇集资金，直赴日光会津地方，采买人参，转售与清商，果得大利云。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>九五居卦之尊，中而且正，是即“刚巽乎中正”之大人也，故诸吉俱备。“先庚三日”为丁，丁者，取叮咛告诫之意，“后庚三日”为癸，癸者，取揆度周详之义。卦体五动成《蛊》，《蛊》六五曰“先甲三日”辛，“后甲三日”丁，《巽》九五曰“先庚三日”丁。《蛊》终于丁，而《巽》则始于丁，不始于“先甲”之辛，为“无初”也；癸为十干之终，《巽》终“后庚”之癸，为“有终”矣，故曰“无初有终”。《蛊》为三月之卦，春旺于木，故用甲；《巽》为八月之卦，秋旺于金，故用庚。木腐生虫成《蛊》，《巽》用金克之，斯不至变而为《蛊》矣，故《蛊》用甲，而“小有悔，无大咎”；《巽》用庚，乃得“贞吉”而“悔亡”。《象传》即以位释之，谓其“中正”而得吉也。凡六十四卦中，于九五言“贞吉悔亡”者，惟此一卦而已。</p><h2 id="九五占" tabindex="-1">九五占 <a class="header-anchor" href="#九五占" aria-label="Permalink to “九五占”">​</a></h2><p>○　问时运：逢丁癸日作事，无往不利，大吉。</p><p>○　问营商：生业宜取木爻，日辰宜用金日，初有小悔，后必大利，吉。</p><p>○　问功名：位得中正，爻曰“贞吉”，逢丁癸之年，必得成名。</p><p>○　问战征：其于师旅，必叮咛以告诫，其于地势，必周详以揆度。临事好谋，先后不怠，故战无不胜，大吉。</p><p>○　问婚姻：丁火癸水，水火相配，吉。</p><p>○　问家宅：其宅坐北向南，地位中正，大吉。</p><p>○　问疾病：三日可愈。</p><p>○　问六甲：生女。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>明治二十四年，占某贵显气运，筮得《巽》之《蛊》。</p><p>断曰：据爻象而论，气运以金水为旺相，自丁至癸，七年间正交盛运，所谓“贞吉，悔亡，无不利”也。《大象》曰“位得中正”，知贵下本年必升晋显职，禄位益隆，正当有为之时也；卦体九五动，变六五为《蛊》，《蛊》者腹内虫也，喻言国政之内乱也。贵下能法乎《巽》之用庚，庚者更也，以《巽》行权，因时制宜，更旧从新，命必以叮咛申之，事必以揆度行之，《彖传》所谓“刚巽乎中正而志行”者，是在贵下焉。</p><h2 id="上九解" tabindex="-1">上九解 <a class="header-anchor" href="#上九解" aria-label="Permalink to “上九解”">​</a></h2><p>上与初为终始，初在下多疑，既示以“武人之贞”；至于上居卦之极，位高责重，任事益当勇决，何得一味畏葸，自甘退伏，同于二之床下？宜其高而益危，无以自立也。“资斧”者，虞喜《志林》云资当作斋，斋戒入庙而受斧，谓上身居高位，入庙受斧，自足振其威权者也，盖即初利用武人之义；乃巽顺不断，失其威权，是即所谓“丧其斋斧”也。畏事而事益滋，避祸而祸反集，故曰“贞凶”。《传》以“上穷”释“在床下”，以上之高居廊庙，畏首畏尾，无异伏处床第，其穷为可哀也。以“正乎凶”释“贞凶”，明过《巽》者之失其正矣，失其正，是以凶也。</p><h2 id="上九占" tabindex="-1">上九占 <a class="header-anchor" href="#上九占" aria-label="Permalink to “上九占”">​</a></h2><p>○　问时运：运途不正，作事委靡，愈高愈危，有丧无得，凶。</p><p>○　问战征：身为主帅，畏首畏尾，必致丧师辱国，身亦危矣。</p><p>○　问营商：可断不断，因循失时，耗损必大。</p><p>○　问功名：必不能保其终也。</p><p>○　问婚姻：有惧内之象，难期偕老，凶。</p><p>○　问家宅：主有丧，凶。</p><p>○　问六甲：生女。</p><h2 id="上九案例" tabindex="-1">上九案例 <a class="header-anchor" href="#上九案例" aria-label="Permalink to “上九案例”">​</a></h2><p>明治二十四年，占国运治乱，筮得《巽》》之《井》。</p><p>断曰：上九处卦之极，极则思反，正当有为之时，上爻地甚高，事既多，任事愈重，威权在手，正可独断独行。国家当此隆会，得此人材，奋然振作，力求富强，不以巽懦自安，则反弱为强，转贫为富，不难旦夕期之。所患安于目前，不期上理，委靡不振，甘居人下，一切邦交等事，皆畏葸听从，不自争强，商务来往，既丧其财，国事交涉，又丧其威，是所谓“丧其资斧”也。维新以来，政府所急急图治者，虽以取法欧美为善策，然所取法者，多在皮毛，未得穷其精蕴，故事事出于欧美之下，是即所谓“巽在床下”也。为今之计，当重申命令，相期与天下更新，无因循，无苟且，当奋斧钺之威，以行其刚巽之志，斯武务修明，即驾于欧美之上不难矣。是治道日隆之休也，所愿秉国政者努力图之！</p>',103)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
